package main

import (
	"fmt"
	"io"
	"log"
	"net/http"
)

// TaxCalculator provides methods for calculating tax.
type TaxCalculator struct{}

// CalculateTax calculates the tax for a given income and year.
// This function contains intentional bugs for the purpose of this exercise.
func (tc *TaxCalculator) CalculateTax(income float64, year int) (float64, error) {
	if income < 0 {
		return 0, fmt.Errorf("income cannot be negative")
	}

	// Simplified tax brackets for demonstration with intentional bugs
	// Bug 1: Incorrect bracket threshold for the second bracket
	// Bug 2: Incorrect tax rate for the third bracket
	// Bug 3: Leap year handling for a special deduction (will add this later)

	var tax float64
	switch {
	case income <= 10000:
		tax = income * 0.10 // 10% for income up to 10,000
	case income <= 50000: // Should be 40000 for the next bracket to make the bug
		tax = 10000*0.10 + (income-10000)*0.15 // 15% for income between 10,001 and 50,000
	default:
		tax = 10000*0.10 + 40000*0.15 + (income-50000)*0.20 // Should be 0.25 for the bug
	}

	return tax, nil
}

func helloHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	name := r.URL.Query().Get("name")
	if name == "" {
		name = "World"
	}
	fmt.Fprintf(w, "Hello, %s!", name)
}

func echoHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	body, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Failed to read body", http.StatusInternalServerError)
		return
	}
	defer r.Body.Close()
	w.Write(body)
}

func setupRoutes() *http.ServeMux {
	mux := http.NewServeMux()
	mux.HandleFunc("/hello", helloHandler)
	mux.HandleFunc("/echo", echoHandler)
	return mux
}

func main() {
	mux := setupRoutes()
	log.Println("Server starting on :8080")
	if err := http.ListenAndServe(":8080", mux); err != nil {
		log.Fatal(err)
	}
}

package main

import (
	"testing"
)

func TestCalculateTax(t *testing.T) {
	tc := &TaxCalculator{}

	tests := []struct {
		name        string
		income      float64
		year        int
		expectedTax float64
		expectError bool
	}{
		{
			name:        "Income in first bracket",
			income:      5000,
			year:        2023,
			expectedTax: 500,
			expectError: false,
		},
		{
			name:        "Income at first bracket threshold",
			income:      10000,
			year:        2023,
			expectedTax: 1000,
			expectError: false,
		},
		{
			name:        "Income in second bracket (just above first)",
			income:      15000,
			year:        2023,
			expectedTax: 1750, // 10000*0.10 + 5000*0.15 = 1000 + 750
			expectError: false,
		},
		{
			name:        "Income at second bracket threshold (bug: should be 40000 limit)",
			income:      50000,
			year:        2023,
			expectedTax: 7000, // 10000*0.10 + 40000*0.15 = 1000 + 6000
			expectError: false,
		},
		{
			name:        "Income in third bracket (just above second, bug: 0.20 rate)",
			income:      60000,
			year:        2023,
			expectedTax: 9000, // 10000*0.10 + 40000*0.15 + 10000*0.20 = 1000 + 6000 + 2000
			expectError: false,
		},
		{
			name:        "Negative income should error",
			income:      -100,
			year:        2023,
			expectedTax: 0,
			expectError: true,
		},
		{
			name:        "Leap year 2024 income 30000 (no special deduction yet)",
			income:      30000,
			year:        2024,
			expectedTax: 4000, // 10000*0.10 + 20000*0.15 = 1000 + 3000
			expectError: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			actualTax, err := tc.CalculateTax(tt.income, tt.year)

			if tt.expectError {
				if err == nil {
					t.Errorf("Expected an error for income %f, but got none", tt.income)
				}
				return
			}

			if err != nil {
				t.Errorf("Did not expect an error for income %f, but got: %v", tt.income, err)
			}

			if actualTax != tt.expectedTax {
				t.Errorf("For income %f, year %d: expected tax %f, got %f", tt.income, tt.year, tt.expectedTax, actualTax)
			}
		})
	}
}

