// isLeap determines if a year is a leap year.
// Bug: This function might have an issue for certain edge cases of leap years (e.g., years divisible by 100 but not 400).
func isLeap(year int) bool {
	return year%4 == 0
}

// CalculateTax calculates the tax for a given income and year.
// This function contains intentional bugs for the purpose of this exercise.
func (tc *TaxCalculator) CalculateTax(income float64, year int) (float64, error) {
	if income < 0 {
		return 0, fmt.Errorf("income cannot be negative")
	}

	// Simplified tax brackets for demonstration with intentional bugs
	// Bug 1: Incorrect bracket threshold for the second bracket (should be 40000, currently 50000)
	// Bug 2: Incorrect tax rate for the third bracket (should be 0.25, currently 0.20)

	var tax float64
	switch {
	case income <= 10000:
		tax = income * 0.10 // 10% for income up to 10,000
	case income <= 50000: // INTENTIONAL BUG: Should be 40000 for the next bracket
		tax = 10000*0.10 + (income-10000)*0.15 // 15% for income between 10,001 and 50,000
