			expectError: false,
		},
		{
			name:        "Leap year 2024 income 45000 (with deduction)",
			income:      45000,
			year:        2024,
			expectedTax: 6250, // (10000*0.10 + 30000*0.15 + 5000*0.25) - 500
			expectError: false,
		},
		{
			name:        "Non-leap year 2023 income 45000 (no deduction)",
			income:      45000,
			year:        2023,
			expectedTax: 6750, // 10000*0.10 + 30000*0.15 + 5000*0.25
			expectError: false,
		},
