				}
				return
			}

			if err != nil {
				t.Errorf("Did not expect an error for income %f, but got: %v", tt.income, err)
			}

			if actualTax != tt.expectedTax {
				t.Errorf("For income %f, year %d: expected tax %f, got %f", tt.income, tt.year, tt.expectedTax, actualTax)
			}
		})
	}
